INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486668-ae328', 'stk-avgeek', 'AE 328', 'info', '{"desc": "جودة المقرر بشكل عام:\nممتازة ويغطي فرع أساسي من فروع التخصص.\nالمواضيع التي يغطيها المقرر :\nبشكل عام Bending, Shear, and Torsion لجميع اجزاء الطائرة.\nالكتاب المستخدم للمقرر:\nT.H.G. Megson “Aircraft Structures for Engineering Students”, 5\nth\n\nEdition, Butterworth Heinenmann, 2015.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nممتازة وكافية لفهم الكونسبت والتحضير للاختبارات.\nمدى فائدته في الناحية التطبيقية:\nمهم جدا من ناحية تصميم اجسام وهياكل الطائرات.\n\nطبعا الكورس يعتبر امتداد ل CE203 ولكن بتركيز مكثف على أجزاء الطائرة, ومع الدكتور وائل 🌹 الله يسعده مايحتاج , متأكد راح يكون أمتع كورس تاخذه 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-328-flight-structures-i/120799/2", "user": "AvGeek", "ts": 1516747189000, "tid": 120799, "pn": 2}}', 1516747189000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522077-ae328', 'stk-user10610', 'AE 328', 'info', '{"desc": "AE328-192\n(لو أنك تبيها الكتف فأنا أنصح فيها اذا كانت أمورك تمام في ce203 و الدكتور وائل حبيب وجددا متساعد )\nـــــ\nجودة المقرر بشكل عام:\nولد عم الce بالضبط يعني هناك كنا نقول beam هنا نقول airfoil , wingbox, fuslage وكذلك المفاهيم العامة في سي اي moment,shear,torsion تبدا تاخذها حبه حبه وتطبقها على أجزاء الطائرة.\nعندنا حالتين اما انك فاهم سي اي فهنا امورك بتمشي تمام ولكن لو ما كنت فاهم عوافي الدكتور بيشرح لك من جديد وانت تذاكر وكذا وامورك تمام ان شاء الله .\nـــــــــــــــــــــ\nأشياء مهمة لازم تتقنها اول ما تمر عليك Ixx,Iyy,Ixy اللي هي مومنت اوف انيرشيا كذلك السينرويد ل x , y واخيرا الshear flow هذي الاشياء ما توقف عند ميجر 1 تمشي معك الى الفاينل ( ما عليك من المسميات حاليا لو كنت تقرا قبل ما تاخذ الكورس) لكن اول ما تمر عليك في الكلاس تاكد انك تعرفها تمام, لان تخيل في نص الكورس عندك سؤال بسيط لكن ما تعرف تبدا اصلا عشان ما تعرف تجيب Ixx.\nــــــــ\nالكورس فيه 5 واجبات و ميجرين كل واحد ساعة ونص و3 كوزات, الواجب طويل نوعا ما لكن لو حليته بنفسك امورك تمام. الدكتور متساعد يعني لو ما قدرت توصل للجواب النهائي بس وضحت له أنك فاهم وكذا ما بيقصر سوا ميجر او كوز أو واجب بيدفك .\nالبونص في المادة كثير يعني ممكن واجب او كوز زيادة او تطلع تشرح على السبورة وتاخذ بونص وعلى مدار السمستر الوضع كذا.\nــــ\nأول كم كلاس كذا الوضع مقدمة ثم الباقي كله حل اسئلة , يعني حاول انك تحل بنفسك كثير ( وما بتحتار يعني وش تحل الدكتور بيرفع لك على البلاكبورد الكوزات والمياجر القديمة للمادة )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-328-flight-structures-i/120799/3", "user": "user10610", "ts": 1589577045000, "tid": 120799, "pn": 3}}', 1589577045000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530069-ae328', 'stk-aerosn', 'AE 328', 'info', '{"desc": "AE328-202\n(مع الدكتور وائل الله يسعده)\nجودة المقرر بشكل عام:\nممتازة جدا، و تعطيك تصور عن الطيارة من ناحية البناء و مقاومة القوى المؤثرة اثناء الطيران مثل قوى الرفع و السحب\nالمادة بشكل عام:\nبينها و بين الCE203 تشابه كبير جدا. المواضيع اللي بتهمك بالمادة من الCE203 هي ال shear flow، bending moment,\nsecond moment of inertia(Ixx,Iyy,Ixy)\n\nمصادر المذاكرة:\nانصح اول شي انك تركز مع الدكتور خلال الشرح، بعدها تذاكر السلايدات و تحل الاسئلة اللي فيها. اذا عندك وقت افتح بعد ما تخلص من السلايدات و اقرا فيه لا تحل الامثلة بس اقرا عشان يعطيك فائدة اكبر و تصور اكثر عن المادة.\n\nكيف تبدع بالكورس:\nزي اي كورس ثاني كل ما حليت اكثر كل ما ابدعت بالاختبارات لكن الميزة هنا ان الحلول سهله بس يعيبها الطول ف حاول انك تفهم البروسيجر حقت الحل و تسجل اغلاطك و تدرب عليها اكثر و بإذن الله فالك اعلى الدرجات.\n\nملاحظات:\nاللي يعيب المادة هذي هو طول الحل ببعض المسائل خصوصا بالبداية (CH18, CH17 , CH19, CH16) و السبب هو وجود التكامل بالحل لكن من CH20 و انت طالع بيصير فيه اختصارات و بتتغير طريقة الحل و تصير اسهل بمليون مرة. ملاحظة ثانية هو ان البونص كثيير بالمادة سواء من واجب اضافي او كويز فحاول انك ما تضيعهم\n\nوفقكم الله جميعا و الله يرزقكم أعلى الدرجات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-328-flight-structures-i/120799/4", "user": "AerosN", "ts": 1621772938000, "tid": 120799, "pn": 4}}', 1621772938000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p91249-ae328', 'stk-user1002', 'AE 328', 'info', '{"desc": "أخي الارهابي\n\nأنا معك قلبا و قالبا\n\nفلقد رأينا من الدكتور الكثير\n\nو الموضوع ليس شخصي\n\nفلا يوجد بيننا و بين هذا الدكتور أي عداوه\n\nو لكن مصلحة الوطن و الذي هو بمصلحة الجامعة و طلابها هو أهم من أي شي\n\nفهذا الدكتور يأخذ راتب شهري و بامكاننا باذن الله ثم بمساعدة المسؤلين أن يتم تغيير هذا الوضع و ايجاد دكتور بديل\n\nو خصوصا أن عقده شارف على الانتهاء و كل ما على المسؤلين فعله هو عدم تجديد عقده\n\nلألا يعاني الباقين من هذه المعاناه\n\nتخيل طالب جامعة الملك فهد النبيه بعد أن يقضي ساعات و أيام على هذه المادة يذاكرها و يفهمها\nثم تكون درجته ما بين 30% و 60% (أنا احد هؤلاء الطلاب)\n\nطبعا أعلى درجة قام هذا الدكتور باعطائها هي تقريبا 70% و تم اعطائها لطالب فيرست أونر تقريبا كل مواده A+ و الباقي A ما عدا هذه المادة طبعا مع هذا الدكتور مع أنه قال لي أنه بذل فيها مجهودا يكاد لا يقارن بأي مادة ثانية\n\nو الأمر من ذلك أنني كنت مع أحد زملاء هذا الدكتور من قسم ثاني و عرف اني طالب هندسة طيران و قال لي هل هذا الدكتور عندكم فقلت له نعم و لكني سمعت أنه شديد مع الطلاب بصورة غير متوقعة(قبل أن آخذ معه أي مادة ) و كنت أقول لا يمكن أن يكون قاسي لهذه الدرجة و التي تتعدى الشدة و تدخل في ظلم الطالب و ابخاسه حقه\nحيث أن سكاشنه اذا فيها 13 طالب ممكن 9 ياخذون F و 2 ياخذون D و 2 ياخذون C الدوافير\nو فوجئت و صعقت عندما قال لي هذا الدكتور ان دكتورنا دائما يتفاخر بأنه يقول أنه هو الدكتور الشديد في قسمنا و هو اللي مهجدنا و مخوفنا (هذا مرض نفسي) و أقر بان هذا الدكتور متكبر جدا و متعالي 😦\n\nو أكتفي بهذا القدر لأني لا أود الاسائة لأي شخص و اذا كانت هناك أي استفسارات و سؤال عن معلومات دقيقة من قبل المختصين فأنا لا مانع لدي لأني لا أريد كتابة الكثير هنا\nو أرجو حذف الموضوع بعد قراءة المختصين له و اتخاذهم الاجراآت اللازمة من قبل المشرفين\nو ذلك لأن الغرض من هذا الموضوع هو ليس ابداء العيوب و لكن لعرض مشكلة عانينا منها لسنين و حاولنا التأقلم معها و لكن لم نستطع\n\nأنا أعتذر عن كل ما قلته لأنها أول مرة أقوم بكتابة شيء مماثل و لن أكتب الا اذا كان فيه اسائة للدين أو هنالك مضرة للوطن\nو لكن كما ذكرت آنفا الموضوع ليس شخصي\nفأنا لن آخذ أي مادة أخرى مع هذا الدكتور لاني خلصت موادي اللي عنده و الحمدلله\n\nو لكن عندما يمس الموضوع مصلحة وطننا فأنا أول المدافعين\nو بالتأكيد الجامعة حريصة على مصلحة الوطن و مصلحتها و مصلحة أبنائها\nو لذلك فنحن نتوقع تفاعل و رد سريع لحل هذه المشكلة التي طالما عانينا منها\n\nو نأمل من الدكتور خالد السلطان و رئيس قسمنا الدكتور أحمد القرني أن يساعدانا في هذا الموضوع لحساسيته و أهميته البالغتين\n\nو شكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-328/49903/3", "user": "user1002", "ts": 1140741941000, "tid": 49903, "pn": 3}}', 1140741941000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p91516-ae328', 'stk-user1403', 'AE 328', 'info', '{"desc": "هذه بعض المواقف المسجلة ضد هذا الدكتور:\n1- الكل يتذكر درجاته السيئة لطلاب الشعبة في فصل 041 البالغ عددهم 8 حيث أعطى أربعة منهم F والأربعة الأخرون D.\n2- اعطائه لاثنين من طلابه الفصل الماضي (051) حرمان بدون انذار مسبق أو اشعار مع العلم أن أحدهمها قد حذف المادة لكن سجل له هذا الدرجة.\n3- عدم اكتراثه بما يأتيه من انذارات حيث مازال يمارس نفس أساليبه.\n\nودمتم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ae-328/49903/7", "user": "user1403", "ts": 1141037472000, "tid": 49903, "pn": 7}}', 1141037472000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-ae328', 'stk-user11372', 'AE 328', 'doc', '{"docs": [{"id": "stk-dr-f98346", "n": "Dr. Wael G. Abdelrahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "AE328 - Term 221\n\nالتحضير : الدكتور من الاخير اسطورة بالتحضير لو جيت بداية الكلاس او نصه بيعطيك حضور\n\nطريقة الشرح : شرح اسطوري برضوا بتركز بتفهم غالبا مشكلة اغلب كلاسات MW وومدتها طويلة بس الشرح الزبدة اسطوري مره\n\nالكويزات : يختبر 3 كويزات ورابع بونص , الثلاثة مستواها قريب مره من الهومورك لاتنسى تحله\n\nالمياجر: مستواها من السلايدات والهوموركات اذا انت فاهم السلايدات والهومورك بتاخذ فل\n\nالفاينلات : نفس المياجر\n\nالقريد النهائي: A+++++++++++++++++++\n\nالصوت: واضضضضضضضضضح\n\nإضافات : الدكتور بالتصحيح شي مو معقول عطه نص الحل وصدقني مابتجيب اقل من 19 من 20 !\nالدكتور متعاون بالردود اوفيس والواتس يرد بسرعة للامانه ومايطول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536129-ae328", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-wael-g-abdelrahman/98346/6", "user": "user11372", "ts": 1673081981000, "tid": 98346, "pn": 6}}]}', 1673081981000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
